// useWorker: false

// ═══════════════════════════════════════════════════════
//  GENEL DEĞİŞKENLER
// ═══════════════════════════════════════════════════════
let _buttons    = [];
let _pendingNav = null;
let _lastLayout = "";
let _mouseX     = -9999;
let _mouseY     = -9999;

// ═══════════════════════════════════════════════════════
//  OYUN DEĞİŞKENLERİ
// ═══════════════════════════════════════════════════════
let _selectedChar = "gurban";
let _currentTurn  = "gurban";
let _scores       = { gurban: 0, mergen: 0 };
// idle | charging | windup | throwing | scatter | done
let _gameState    = "idle";
let _stateTimer   = 0;

// Güç çubuğu
let _power        = 0;
let _powerDir     = 1;
let _pendingThrow = false;
let _storedPower  = 0;   // "at" anındaki güç değeri

// Atılan kemik – parabolik fizik
let _kemikInst    = null;
let _kemikStartX  = 0;
let _kemikStartY  = 0;
let _kemikVx0     = 0;
let _kemikVy0     = 0;
let _kemikFlight  = 0;
let _kemikElapsed = 0;
const GRAVITY     = 1600;

// Yer kemikleri
let _yerList = [];   // { inst, vx, vy, state:'still'|'flyout'|'gone', timer }

// Karakter animasyonu (windup sırasında)
let _animFrame = 0;
let _animTimer = 0;
const ANIM_FPS = 8;   // 4 kare × 0.125 s = 0.5 sn

// Halka merkezi
const RING_CX = 963;
const RING_CY = 763;

// Yarım daire yay (∩ bombesi yukarı)
const ARC_R    = 80;
const ARC_CX   = 100;
const ARC_CY   = 110;
const ARC_CIRC = Math.PI * ARC_R;
const ARC_PATH = `M ${ARC_CX - ARC_R} ${ARC_CY} A ${ARC_R} ${ARC_R} 0 0 1 ${ARC_CX + ARC_R} ${ARC_CY}`;

// DOM
let _powerBarEl  = null;
let _arcFillEl   = null;
let _arcShineEl  = null;
let _turnLabelEl = null;
let _winnerEl    = null;
let _shadowEl    = null;

// Ses sistemi — base64 gömülü (URL fetch'e gerek yok)
const _SFX_DATA = {
    carpma:  "data:audio/webm;base64,",
    skorses: "data:audio/webm;base64,"
};

// Skor sprite pop animasyonu
// t: -1 → pasif, 0+ → animasyon zamanı (saniye)
let _skorAnim = {
    gurban: { t: -1, origW: 0, origH: 0 },
    mergen: { t: -1, origW: 0, origH: 0 }
};

// ═══════════════════════════════════════════════════════
//  BAŞLANGIÇ
// ═══════════════════════════════════════════════════════
runOnStartup(async runtime =>
{
    // Ses ön yükleme (base64 data URL — fetch gerektirmez)
    // Tarayıcı AudioContext kilidini açmak için pointerdown bekle

    window.addEventListener("pointermove", e =>
    {
        const p = _toLayout(e.clientX, e.clientY);
        _mouseX = p.x;
        _mouseY = p.y;
    });

    window.addEventListener("pointerdown", e =>
    {
        _resumeAudio();   // tarayıcı ses kilidini aç
        if (e.button !== 0) return;
        const p = _toLayout(e.clientX, e.clientY);

        for (const b of _buttons)
        {
            if (b.inst.containsPoint(p.x, p.y))
            {
                if (b.charSel) _selectedChar = b.charSel;
                _pendingNav = b.target;
                return;
            }
        }

        if (_gameState === "charging")
            _pendingThrow = true;
    });

    window.addEventListener("keydown", e =>
    {
        if (e.code === "Space" && _gameState === "charging")
        {
            e.preventDefault();
            _pendingThrow = true;
        }
    });

    runtime.addEventListener("beforeprojectstart", () =>
    {
        runtime.addEventListener("tick", () => _tick(runtime));
    });
});

// ═══════════════════════════════════════════════════════
//  KOORDİNAT ÇEVİRME
// ═══════════════════════════════════════════════════════
function _toLayout(cx, cy)
{
    const cv = document.querySelector("canvas");
    if (!cv) return { x: 0, y: 0 };
    const r  = cv.getBoundingClientRect();
    const sc = Math.min(r.width / 1920, r.height / 1080);
    const ox = (r.width  - 1920 * sc) / 2;
    const oy = (r.height - 1080 * sc) / 2;
    return { x: (cx - r.left - ox) / sc, y: (cy - r.top - oy) / sc };
}

function _toScreen(lx, ly)
{
    const cv = document.querySelector("canvas");
    if (!cv) return { x: 0, y: 0 };
    const r  = cv.getBoundingClientRect();
    const sc = Math.min(r.width / 1920, r.height / 1080);
    const ox = (r.width  - 1920 * sc) / 2;
    const oy = (r.height - 1080 * sc) / 2;
    return { x: r.left + ox + lx * sc, y: r.top + oy + ly * sc };
}

// ═══════════════════════════════════════════════════════
//  LAYOUT KURULUMU
// ═══════════════════════════════════════════════════════
function _setup(runtime)
{
    _buttons      = [];
    _pendingNav   = null;
    _pendingThrow = false;
    _gameState    = "idle";
    _removeDom();

    const name = runtime.layout.name;

    if (name === "giris")
    {
        _addNavBtn(runtime, "btn_nasiloynanir", "bilgi");
        _addCharBtn(runtime, "karakter_gurban", "gurban");
        _addCharBtn(runtime, "karakter_mergen", "mergen");
    }
    else if (name === "bilgi")
    {
        _addNavBtn(runtime, "btn_anasayfa", "giris");
    }
    else if (name === "oyun")
    {
        _setupOyun(runtime);
    }
}

function _addNavBtn(runtime, objName, target)
{
    const inst = runtime.objects[objName]?.getFirstInstance();
    if (!inst) return;
    _buttons.push({ inst, target, charSel: null, t: 0, origW: inst.width, origH: inst.height });
}

function _addCharBtn(runtime, objName, charSel)
{
    const inst = runtime.objects[objName]?.getFirstInstance();
    if (!inst) return;
    _buttons.push({ inst, target: "oyun", charSel, t: 0, origW: inst.width, origH: inst.height });
}

// ═══════════════════════════════════════════════════════
//  OYUN KURULUMU
// ═══════════════════════════════════════════════════════
function _setupOyun(runtime)
{
    _scores      = { gurban: 0, mergen: 0 };
    _currentTurn = _selectedChar;
    _animFrame   = 0;
    _animTimer   = 0;

    _kemikInst = runtime.objects.kemik?.getFirstInstance();
    if (_kemikInst) _kemikInst.isVisible = false;

    const gInst = runtime.objects.gurban?.getFirstInstance();
    const mInst = runtime.objects.mergen?.getFirstInstance();
    if (gInst) gInst.animationFrame = 0;
    if (mInst) mInst.animationFrame = 0;

    _yerList = [];
    const ykType = runtime.objects.yer_kemik1;
    if (ykType)
    {
        for (const inst of ykType.getAllInstances())
        {
            inst.isVisible = true;
            _yerList.push({ inst, vx: 0, vy: 0, state: "still", timer: 0 });
        }
    }

    // Skor sprite orijinal boyutlarını kaydet
    const gsInst = runtime.objects.gurbanskor?.getFirstInstance();
    const msInst = runtime.objects.mergenskor?.getFirstInstance();
    if (gsInst) { _skorAnim.gurban.origW = gsInst.width; _skorAnim.gurban.origH = gsInst.height; _skorAnim.gurban.t = -1; }
    if (msInst) { _skorAnim.mergen.origW = msInst.width; _skorAnim.mergen.origH = msInst.height; _skorAnim.mergen.t = -1; }

    _createShadowEl(runtime);
    _createPowerBar(runtime);
    _updateSpriteScores(runtime);
    _startTurn(runtime);
}

// ═══════════════════════════════════════════════════════
//  TUR YÖNETİMİ
// ═══════════════════════════════════════════════════════
function _startTurn(runtime)
{
    _power        = 0;
    _powerDir     = 1;
    _pendingThrow = false;
    _gameState    = "charging";
    _animFrame    = 0;
    _animTimer    = 0;

    const cInst = runtime.objects[_currentTurn]?.getFirstInstance();
    if (cInst) cInst.animationFrame = 0;

    if (_powerBarEl)
    {
        _powerBarEl.style.display = "";
        _updatePowerBarPos(runtime);
    }
    _updateTurnLabel();
}

function _endTurn(runtime)
{
    const stillLeft = _yerList.some(yk => yk.state === "still");

    if (!stillLeft)
    {
        _gameState = "done";
        _removePowerBar();
        _showWinner(runtime);
    }
    else
    {
        _currentTurn = (_currentTurn === "gurban") ? "mergen" : "gurban";
        _startTurn(runtime);
    }
}

// ═══════════════════════════════════════════════════════
//  ATIŞ – AŞAMA 1: Windup (animasyon önce, kemik sonra)
// ═══════════════════════════════════════════════════════
function _executeThrow(runtime)
{
    _gameState    = "windup";
    _pendingThrow = false;
    _storedPower  = _power;

    if (_powerBarEl) _powerBarEl.style.display = "none";

    _animFrame = 0;
    _animTimer = 0;
    const cInst = runtime.objects[_currentTurn]?.getFirstInstance();
    if (cInst) cInst.animationFrame = 0;
}

// ═══════════════════════════════════════════════════════
//  ATIŞ – AŞAMA 2: Frame 3 görününce kemik fırlat
// ═══════════════════════════════════════════════════════
function _launchKemik(runtime)
{
    _gameState = "throwing";

    if (_kemikInst)
    {
        _kemikInst.isVisible = true;

        const fromLeft = (_currentTurn === "gurban");
        const sx = fromLeft ? 210 : 1710;
        const sy = 650;

        _kemikInst.x     = _kemikStartX = sx;
        _kemikInst.y     = _kemikStartY = sy;
        _kemikInst.angle = 0;
        _kemikElapsed    = 0;

        const spd = 750 + (_storedPower / 100) * 600;
        _kemikVx0  = fromLeft ? spd : -spd;

        const dx = RING_CX - sx;
        _kemikFlight = dx / _kemikVx0;

        _kemikVy0 = (RING_CY - sy - 0.5 * GRAVITY * _kemikFlight * _kemikFlight)
                    / _kemikFlight;
    }
}

// ═══════════════════════════════════════════════════════
//  SES SİSTEMİ  –  Görünür Tanılama + Çoklu Yöntem
// ═══════════════════════════════════════════════════════
let _dbgEl   = null;
let _dbgLines = [];

function _dbg(msg)
{
    console.log("[SES]", msg);
    if (!_dbgEl)
    {
        _dbgEl = document.createElement("div");
        _dbgEl.style.cssText = [
            "position:fixed", "top:5px", "right:5px",
            "background:rgba(0,0,0,0.85)", "color:#0f0",
            "font:11px/1.4 monospace", "padding:6px 8px",
            "z-index:99999", "max-width:340px",
            "pointer-events:none", "white-space:pre-wrap",
            "border:1px solid #0f0"
        ].join(";");
        document.body.appendChild(_dbgEl);
    }
    _dbgLines.push(msg);
    if (_dbgLines.length > 8) _dbgLines.shift();
    _dbgEl.textContent = _dbgLines.join("\n");
}


function _resumeAudio()
{
    // base64 yaklaşımında AudioContext kilidi gerekmiyor
}

function _playSound(runtime, name)
{
    const url = _SFX_DATA[name];
    if (!url) { _dbg(`ses: bilinmeyen: ${name}`); return; }
    try
    {
        const a = new Audio(url);
        a.volume = 0.75;
        a.play().catch(e => _dbg(`ses hata: ${e.message?.slice(0,40)}`));
    }
    catch(e) { _dbg(`ses ex: ${e.message?.slice(0,40)}`); }
}

// ═══════════════════════════════════════════════════════
//  DAĞILMA  (bilyar fiziği + dönüş + cascade)
// ═══════════════════════════════════════════════════════
function _triggerScatter(runtime)
{
    if (_kemikInst) _kemikInst.isVisible = false;

    _playSound(runtime, "carpma");   // çarpma sesi

    const cInst = runtime.objects[_currentTurn]?.getFirstInstance();
    if (cInst) cInst.animationFrame = 0;

    const stillBones = _yerList.filter(yk => yk.state === "still");

    // ── Atılan kemiğin geliş yönü (normalize) ─────────
    const impLen = Math.hypot(_kemikVx0, _kemikVy0) || 1;
    const impX   = _kemikVx0 / impLen;   // geliş yönü birimi
    const impY   = _kemikVy0 / impLen;
    const perpX  = -impY;                // geliş yönüne dik
    const perpY  =  impX;

    let pts = 0;

    for (const yk of stillBones)
    {
        // Kemikten merkeze vektör
        const dx   = yk.inst.x - RING_CX;
        const dy   = yk.inst.y - RING_CY;
        const dist = Math.hypot(dx, dy) || 1;

        // Geliş yönüyle hizalama: +1 = tam karşıda, -1 = arkada
        const dot = (dx * impX + dy * impY) / dist;

        // Çarpılma olasılığı: geliş yönündeki ve yakın kemikler daha yüksek
        const hitProb = 0.48 + dot * 0.28 + Math.max(0, 1 - dist / 180) * 0.30;
        if (Math.random() > hitProb) continue;

        // ── Çıkış yönü hesabı (bilyar modeli) ────────
        // 1. Merkez-dışı radyal bileşen
        let exitX = dx / dist;
        let exitY = dy / dist;

        // 2. Geliş momentumu katkısı (doğrudan darbeden gelen enerji)
        exitX += impX * 0.65;
        exitY += impY * 0.65;

        // 3. Dik yönde rastgele saçılım (karmaşıklık için)
        const lateral = (Math.random() - 0.5) * 0.9;
        exitX += perpX * lateral;
        exitY += perpY * lateral;

        // 4. Tamamen rastgele küçük gürültü
        exitX += (Math.random() - 0.5) * 0.3;
        exitY += (Math.random() - 0.5) * 0.3;

        // Normalize
        const len = Math.hypot(exitX, exitY) || 1;
        exitX /= len;
        exitY /= len;

        // ── Hız: hızlı başla, kısa mesafede dur ──────
        // max_mesafe ≈ speed / decel  →  ~140-280 px (halka dışı, karakterlere ulaşmaz)
        const closeBonus = Math.max(0, 1 - dist / 170) * 200;
        const speed = 600 + Math.random() * 350 + closeBonus;

        yk.state = "flyout";
        yk.timer = 0;
        yk.delay = Math.random() * 0.07;       // cascade: maks 70 ms gecikme
        yk.vx    = exitX * speed;
        yk.vy    = exitY * speed;
        yk.spin  = (Math.random() - 0.5) * 24; // ±12 rad/s dönüş
        yk.decel = 3.5 + Math.random() * 1.5;  // yüksek sürtünme → kısa mesafe
        pts++;
    }

    _scores[_currentTurn] += pts;
    _gameState  = "scatter";
    _stateTimer = 0;
    _updateSpriteScores(runtime);
    if (pts > 0) _triggerSkorAnim(runtime, _currentTurn);
}

// ═══════════════════════════════════════════════════════
//  ANA TİCK
// ═══════════════════════════════════════════════════════
function _tick(runtime)
{
    const name = runtime.layout.name;
    if (name !== _lastLayout)
    {
        _lastLayout = name;
        _setup(runtime);
    }

    if (_pendingNav)
    {
        const nav = _pendingNav;
        _pendingNav = null;
        runtime.goToLayout(nav);
        return;
    }

    const dt = runtime.dt;

    for (const b of _buttons)
    {
        const over = b.inst.containsPoint(_mouseX, _mouseY);
        b.t += ((over ? 1 : 0) - b.t) * Math.min(8 * dt, 1);
        const s = 1 + b.t * 0.08;
        b.inst.width    = b.origW * s;
        b.inst.height   = b.origH * s;
        b.inst.colorRgb = [1, 1, 1 - b.t * 0.35];
    }

    if (name === "oyun")
        _tickOyun(runtime, dt);
}

function _tickOyun(runtime, dt)
{
    if (_gameState === "charging")
    {
        _power += _powerDir * 85 * dt;
        if (_power >= 100) { _power = 100; _powerDir = -1; }
        if (_power <=   0) { _power =   0; _powerDir =  1; }

        const offset = ARC_CIRC * (1 - _power / 100);
        if (_arcFillEl)  _arcFillEl.setAttribute("stroke-dashoffset",  offset.toFixed(2));
        if (_arcShineEl) _arcShineEl.setAttribute("stroke-dashoffset", offset.toFixed(2));

        if (_pendingThrow)
            _executeThrow(runtime);
    }
    else if (_gameState === "windup")
    {
        // ── Önce animasyon: 0 → 1 → 2 → 3 ───────────────
        _animTimer += dt;
        if (_animTimer >= 1 / ANIM_FPS)
        {
            _animTimer = 0;
            _animFrame++;

            if (_animFrame <= 3)
            {
                const cInst = runtime.objects[_currentTurn]?.getFirstInstance();
                if (cInst) cInst.animationFrame = _animFrame;

                if (_animFrame === 3)
                    _launchKemik(runtime);
            }
        }
    }
    else if (_gameState === "throwing")
    {
        if (_kemikInst && _kemikInst.isVisible)
        {
            _kemikElapsed += dt;
            const t = _kemikElapsed;
            _kemikInst.x     = _kemikStartX + _kemikVx0 * t;
            _kemikInst.y     = _kemikStartY + _kemikVy0 * t + 0.5 * GRAVITY * t * t;
            _kemikInst.angle += 8 * Math.PI * dt;

            if (_kemikElapsed >= _kemikFlight)
                _triggerScatter(runtime);
        }
    }
    else if (_gameState === "scatter")
    {
        _stateTimer += dt;

        for (const yk of _yerList)
        {
            if (yk.state !== "flyout") continue;

            // Cascade gecikmesi
            if (yk.delay > 0) { yk.delay -= dt; continue; }

            yk.timer  += dt;

            // Konum güncelle
            yk.inst.x += yk.vx * dt;
            yk.inst.y += yk.vy * dt;

            // Üstel sürtünme (daha gerçekçi yavaşlama)
            const f  = Math.exp(-yk.decel * dt);
            yk.vx   *= f;
            yk.vy   *= f;

            // Dönüş (kademeli azalır)
            yk.inst.angle += yk.spin * dt;
            yk.spin       *= Math.exp(-2.8 * dt);

            if (yk.timer > 1.5)
            {
                yk.state = "gone";
                yk.inst.isVisible = false;
            }
        }

        if (_stateTimer > 2.4)
            _endTurn(runtime);
    }

    // Skor sprite pop animasyonu (tüm state'lerde çalışır)
    _tickSkorAnim(runtime, dt);
}

// ═══════════════════════════════════════════════════════
//  SKOR SPRİTE POP ANİMASYONU
// ═══════════════════════════════════════════════════════
function _triggerSkorAnim(runtime, who)
{
    _skorAnim[who].t = 0;
    _createSkorGlow(runtime, who);
    _playSound(runtime, "skorses");   // skor sesi
}

function _tickSkorAnim(runtime, dt)
{
    const DUR = 1.4;   // toplam animasyon süresi (sn)

    for (const who of ["gurban", "mergen"])
    {
        const sa = _skorAnim[who];
        if (sa.t < 0) continue;   // pasif

        sa.t += dt;

        const objName = who + "skor";
        const inst    = runtime.objects[objName]?.getFirstInstance();
        if (!inst) { sa.t = -1; continue; }

        if (sa.t >= DUR)
        {
            // Orijinal boyuta geri dön
            inst.width  = sa.origW;
            inst.height = sa.origH;
            sa.t = -1;
        }
        else
        {
            const p = sa.t / DUR;

            let scale;
            if (p < 0.18)
            {
                // 0 → 0.18 : hızlı büyüme (1.0 → 1.40)
                scale = 1 + (p / 0.18) * 0.40;
            }
            else
            {
                // 0.18 → 1.0 : yavaş geri dönüş + hafif zıplama
                const q = (p - 0.18) / 0.82;
                // Dampened sine: 1.40 → 1.00 + küçük overshoot
                scale = 1 + (1 - q) * 0.40 + Math.sin(q * Math.PI * 2.5) * 0.035 * (1 - q);
            }

            inst.width  = sa.origW * scale;
            inst.height = sa.origH * scale;
        }
    }
}

function _createSkorGlow(runtime, who)
{
    const key = "c3-skor-glow-" + who;
    document.getElementById(key)?.remove();

    const inst = runtime.objects[who + "skor"]?.getFirstInstance();
    if (!inst) return;

    // Sprite'ın alt-ortasını ekran koordinatına çevir
    const pos = _toScreen(inst.x, inst.y + inst.height * 0.45);

    // CSS keyframe (bir kez eklenir)
    if (!document.getElementById("c3-glow-kf"))
    {
        const s = document.createElement("style");
        s.id = "c3-glow-kf";
        s.textContent =
            "@keyframes c3GlowPop{" +
                "0%  {opacity:0;transform:translate(-50%,-50%) scale(0.3)}" +
                "20% {opacity:1;transform:translate(-50%,-50%) scale(1)}" +
                "70% {opacity:0.7;transform:translate(-50%,-50%) scale(1.3)}" +
                "100%{opacity:0;transform:translate(-50%,-50%) scale(1.8)}" +
            "}";
        document.head.appendChild(s);
    }

    const el = document.createElement("div");
    el.id = key;
    el.style.cssText =
        "position:fixed;" +
        "left:" + pos.x + "px;top:" + pos.y + "px;" +
        "width:200px;height:50px;" +
        "border-radius:50%;" +
        "background:radial-gradient(ellipse at center," +
            "rgba(255,240,80,0.95) 0%,rgba(255,160,0,0.60) 40%,rgba(255,80,0,0) 70%);" +
        "filter:blur(12px);" +
        "pointer-events:none;z-index:9000;" +
        "animation:c3GlowPop 1.4s ease-out forwards;";

    document.body.appendChild(el);
    setTimeout(() => el.remove(), 1500);
}

// ═══════════════════════════════════════════════════════
//  DOM – KARAKTER ZEMİN GÖLGELERİ
// ═══════════════════════════════════════════════════════
function _createShadowEl(runtime)
{
    document.getElementById("c3-char-shadows")?.remove();

    const cv = document.querySelector("canvas");
    const r  = cv?.getBoundingClientRect();
    if (!r) return;
    const sc = Math.min(r.width / 1920, r.height / 1080);

    const wrap = document.createElement("div");
    wrap.id = "c3-char-shadows";
    wrap.style.cssText = "position:fixed;top:0;left:0;pointer-events:none;z-index:91;";

    const chars = [
        { name: "gurban", originY: 0.499 },
        { name: "mergen", originY: 0.505 }
    ];

    for (const ch of chars)
    {
        const inst = runtime.objects[ch.name]?.getFirstInstance();
        if (!inst) continue;

        // Ayak pozisyonu (layout → ekran) + hafif aşağı kaydırma
        const feetLy = inst.y + inst.height * (1 - ch.originY) + 8;
        const pos    = _toScreen(inst.x, feetLy);

        // Gölge boyutu: karakterin ~2.5x genişliği kadar yatay oval
        const sw = Math.round(inst.width * sc * 2.5);
        const sh = Math.round(sw * 0.22);

        const el = document.createElement("div");
        el.style.cssText =
            "position:fixed;" +
            "left:" + pos.x + "px;" +
            "top:"  + pos.y + "px;" +
            "transform:translate(-50%,-50%);" +
            "width:"  + sw + "px;" +
            "height:" + sh + "px;" +
            "border-radius:50%;" +
            "background:radial-gradient(ellipse at center," +
                "rgba(0,0,0,0.55) 0%,rgba(0,0,0,0.20) 40%,rgba(0,0,0,0) 70%);" +
            "filter:blur(6px);" +
            "pointer-events:none;";

        wrap.appendChild(el);
    }

    document.body.appendChild(wrap);
    _shadowEl = wrap;
}

// ═══════════════════════════════════════════════════════
//  DOM – GÜÇ ÇUBUĞU (SVG yarım daire)
// ═══════════════════════════════════════════════════════
function _createPowerBar(runtime)
{
    _removePowerBar();

    const ns = "http://www.w3.org/2000/svg";

    const bar = document.createElement("div");
    bar.id = "c3-power-bar";
    bar.style.cssText =
        "position:fixed;z-index:9999;pointer-events:none;user-select:none;" +
        "text-align:center;";

    const lbl = document.createElement("div");
    lbl.id = "c3-turn-label";
    lbl.style.cssText =
        "font-family:'Arial Black',Arial,sans-serif;font-size:20px;font-weight:bold;" +
        "color:#ffe066;text-shadow:2px 2px 6px #000,0 0 14px #000;" +
        "margin-bottom:2px;letter-spacing:2px;";
    bar.appendChild(lbl);

    const svg = document.createElementNS(ns, "svg");
    svg.setAttribute("width",   "200");
    svg.setAttribute("height",  "120");
    svg.setAttribute("viewBox", "0 0 200 120");
    svg.setAttribute("overflow", "visible");

    const defs = document.createElementNS(ns, "defs");

    const flt = document.createElementNS(ns, "filter");
    flt.setAttribute("id", "c3g"); flt.setAttribute("x", "-40%"); flt.setAttribute("y", "-40%");
    flt.setAttribute("width", "180%"); flt.setAttribute("height", "180%");
    const gBlur = document.createElementNS(ns, "feGaussianBlur");
    gBlur.setAttribute("stdDeviation", "5"); gBlur.setAttribute("result", "b");
    const gMerge = document.createElementNS(ns, "feMerge");
    const gm1 = document.createElementNS(ns, "feMergeNode"); gm1.setAttribute("in", "b");
    const gm2 = document.createElementNS(ns, "feMergeNode"); gm2.setAttribute("in", "SourceGraphic");
    gMerge.appendChild(gm1); gMerge.appendChild(gm2);
    flt.appendChild(gBlur); flt.appendChild(gMerge);
    defs.appendChild(flt);

    const grad = document.createElementNS(ns, "linearGradient");
    grad.setAttribute("id", "c3gr"); grad.setAttribute("x1", "0%"); grad.setAttribute("x2", "100%");
    for (const [off, col] of [["0%","#2ecc71"],["50%","#f1c40f"],["100%","#e74c3c"]])
    {
        const s = document.createElementNS(ns, "stop");
        s.setAttribute("offset", off); s.setAttribute("stop-color", col);
        grad.appendChild(s);
    }
    defs.appendChild(grad);

    const gradS = document.createElementNS(ns, "linearGradient");
    gradS.setAttribute("id", "c3gri"); gradS.setAttribute("x1", "0%"); gradS.setAttribute("x2", "100%");
    for (const [off, col] of [["0%","rgba(255,255,255,0.35)"],["50%","rgba(255,255,255,0.10)"],["100%","rgba(255,255,255,0.35)"]])
    {
        const s = document.createElementNS(ns, "stop");
        s.setAttribute("offset", off); s.setAttribute("stop-color", col);
        gradS.appendChild(s);
    }
    defs.appendChild(gradS);

    svg.appendChild(defs);

    const bgShadow = document.createElementNS(ns, "path");
    bgShadow.setAttribute("d", ARC_PATH); bgShadow.setAttribute("fill", "none");
    bgShadow.setAttribute("stroke", "rgba(0,0,0,0.55)"); bgShadow.setAttribute("stroke-width", "22");
    bgShadow.setAttribute("stroke-linecap", "round");
    svg.appendChild(bgShadow);

    const bgArc = document.createElementNS(ns, "path");
    bgArc.setAttribute("d", ARC_PATH); bgArc.setAttribute("fill", "none");
    bgArc.setAttribute("stroke", "#1a1a2e"); bgArc.setAttribute("stroke-width", "16");
    bgArc.setAttribute("stroke-linecap", "round");
    svg.appendChild(bgArc);

    const bgLine = document.createElementNS(ns, "path");
    bgLine.setAttribute("d", ARC_PATH); bgLine.setAttribute("fill", "none");
    bgLine.setAttribute("stroke", "rgba(255,255,255,0.08)"); bgLine.setAttribute("stroke-width", "14");
    bgLine.setAttribute("stroke-linecap", "round"); bgLine.setAttribute("stroke-dasharray", "4 8");
    svg.appendChild(bgLine);

    const fillArc = document.createElementNS(ns, "path");
    fillArc.setAttribute("d", ARC_PATH); fillArc.setAttribute("fill", "none");
    fillArc.setAttribute("stroke", "url(#c3gr)"); fillArc.setAttribute("stroke-width", "13");
    fillArc.setAttribute("stroke-linecap", "round"); fillArc.setAttribute("filter", "url(#c3g)");
    fillArc.setAttribute("stroke-dasharray", ARC_CIRC.toFixed(2) + " " + (ARC_CIRC + 10).toFixed(2));
    fillArc.setAttribute("stroke-dashoffset", ARC_CIRC.toFixed(2));
    svg.appendChild(fillArc);

    const fillShine = document.createElementNS(ns, "path");
    fillShine.setAttribute("d", ARC_PATH); fillShine.setAttribute("fill", "none");
    fillShine.setAttribute("stroke", "url(#c3gri)"); fillShine.setAttribute("stroke-width", "5");
    fillShine.setAttribute("stroke-linecap", "round");
    fillShine.setAttribute("stroke-dasharray", ARC_CIRC.toFixed(2) + " " + (ARC_CIRC + 10).toFixed(2));
    fillShine.setAttribute("stroke-dashoffset", ARC_CIRC.toFixed(2));
    svg.appendChild(fillShine);

    bar.appendChild(svg);

    const hint = document.createElement("div");
    hint.style.cssText =
        "font-family:Arial,sans-serif;font-size:15px;" +
        "color:rgba(255,255,255,0.85);text-shadow:1px 1px 4px #000;" +
        "margin-top:2px;letter-spacing:1px;";
    hint.textContent = "TIKLA veya SPACE";
    bar.appendChild(hint);

    document.body.appendChild(bar);
    _powerBarEl  = bar;
    _arcFillEl   = fillArc;
    _arcShineEl  = fillShine;
    _turnLabelEl = lbl;

    _updatePowerBarPos(runtime);
}

function _updatePowerBarPos(runtime)
{
    if (!_powerBarEl) return;
    const cInst = runtime.objects[_currentTurn]?.getFirstInstance();
    if (!cInst) return;
    const headLy = cInst.y - cInst.height * 0.5;
    const pos    = _toScreen(cInst.x, headLy);
    _powerBarEl.style.left      = pos.x + "px";
    _powerBarEl.style.top       = (pos.y - 8) + "px";
    _powerBarEl.style.transform = "translate(-50%, -100%)";
}

function _removePowerBar()
{
    document.getElementById("c3-power-bar")?.remove();
    _powerBarEl  = null;
    _arcFillEl   = null;
    _arcShineEl  = null;
    _turnLabelEl = null;
}

// ═══════════════════════════════════════════════════════
//  SPRİTE SKOR GÜNCELLEMESİ
// ═══════════════════════════════════════════════════════
function _updateSpriteScores(runtime)
{
    const gs = runtime.objects.gurbanskor?.getFirstInstance();
    const ms = runtime.objects.mergenskor?.getFirstInstance();
    if (gs) gs.animationFrame = _scores.gurban;
    if (ms) ms.animationFrame = _scores.mergen;
}

// ═══════════════════════════════════════════════════════
//  DOM – KAZANAN EKRANI
// ═══════════════════════════════════════════════════════
function _showWinner(runtime)
{
    // Sprite skorlarını son kez güncelle
    _updateSpriteScores(runtime);

    const g   = _scores.gurban, m = _scores.mergen;
    const txt = g > m ? "GURBAN KAZANDI!" :
                m > g ? "MERGEN KAZANDI!" :
                        "BERABERE!";

    document.getElementById("c3-winner")?.remove();

    const el = document.createElement("div");
    el.id = "c3-winner";
    el.style.cssText =
        "position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);" +
        "z-index:9999;text-align:center;pointer-events:none;user-select:none;";

    el.innerHTML =
        `<div style="` +
            `background:linear-gradient(160deg,#190b00,#2e1500 50%,#190b00);` +
            `border:2.5px solid #b8730a;border-radius:16px;padding:28px 48px;` +
            `box-shadow:0 0 40px rgba(184,115,10,0.65),inset 0 0 30px rgba(0,0,0,0.65);` +
        `">` +
            `<div style="font-family:'Times New Roman',serif;font-size:11px;letter-spacing:5px;color:rgba(200,134,10,0.65);margin-bottom:12px;">── SONUÇ ──</div>` +
            `<div style="font-family:Impact,'Arial Black',Arial,sans-serif;font-size:40px;letter-spacing:2px;color:#ffe066;text-shadow:0 0 26px rgba(255,220,60,0.95);margin-bottom:22px;">${txt}</div>` +
            `<button id="c3-play-again" style="` +
                `pointer-events:auto;cursor:pointer;` +
                `background:linear-gradient(180deg,#d4920f,#7a4400);` +
                `border:2px solid #e8a820;border-radius:10px;` +
                `color:#fff;font-family:Impact,'Arial Black',Arial,sans-serif;` +
                `font-size:20px;letter-spacing:3px;padding:13px 40px;` +
                `text-shadow:1px 1px 4px rgba(0,0,0,0.9);` +
                `box-shadow:0 4px 16px rgba(0,0,0,0.75),inset 0 1px 0 rgba(255,255,255,0.22);` +
                `outline:none;` +
            `">TEKRAR OYNA</button>` +
        `</div>`;

    el.addEventListener("pointerdown", e =>
    {
        const btn = e.target.id === "c3-play-again"
            ? e.target
            : e.target.closest?.("#c3-play-again");
        if (btn) { e.stopPropagation(); _pendingNav = "giris"; }
    });

    document.body.appendChild(el);
    _winnerEl = el;
}

function _updateTurnLabel()
{
    if (!_turnLabelEl) return;
    _turnLabelEl.textContent =
        (_currentTurn === "gurban" ? "KURBAN" : "MERGEN") + " ATIYOR";
}

function _removeDom()
{
    _removePowerBar();
    document.getElementById("c3-winner")?.remove();
    _winnerEl = null;
    document.getElementById("c3-char-shadows")?.remove();
    _shadowEl = null;
}
